function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function contextNavigation(){
  if(state.page==='home')return '<span class="header-caption">Your experts. Your perspective.</span>';
  if(state.page==='experts'||state.page==='expert')return '<span class="header-divider"></span><button class="header-link" data-action="navigate" data-page="experts">Chuyên gia AI</button>';
  if(state.page==='chat'||state.page==='direct-picker'){const back=state.page==='chat'?currentDirectChat()?.returnPage:state.chatReturn;return `<span class="header-divider"></span><button class="header-link" data-action="navigate" data-page="${back||'templates'}">${back==='experts'?'Chuyên gia AI':'Tạo case'}</button><span class="header-separator">/</span><span class="header-caption">Trao đổi riêng</span>`;}
  return `<span class="header-divider"></span><button class="header-link" data-action="navigate" data-page="cases">Cases</button>${state.page!=='cases'?`<span class="header-separator">/</span><span class="header-caption">${pageNames[state.page]}</span>`:''}`;
}
function prototypeMenu(){return `<details class="dev-menu"><summary>Prototype ${ico('settings')}</summary><div class="dev-popover"><span class="small muted">Công cụ xem giao diện mẫu</span><label class="label tiny-gap" for="preview-state">Màn hình mẫu</label><select id="preview-state"><option value="">Chọn trạng thái…</option><option value="running">Đang chạy</option><option value="complete">Hoàn tất</option><option value="partial">Thoát sớm</option></select><button class="text-button tiny-gap" data-action="toggle-state">Xem state frontend</button><button class="text-button tiny-gap" data-action="reset">Đặt lại prototype</button></div></details>`;}
function render(){
  const route=state.page+(state.page==='setup'?':'+state.wizard:state.page==='expert'?':'+(state.expertId||'new')+':'+state.expertEditing:state.page==='dashboard'?':'+state.dashboardView:state.page==='chat'?':'+state.chatId:'');
  const routeChanged=render.route!==route;
  const selectedId=state.page==='running'?state.run?.selectedStep:state.selectedStep;
  const selectedChanged=render.selectedStep!==selectedId;
  const planning=isPlanEditor()||state.page==='running'||state.page==='dashboard'&&state.dashboardView==='map'||state.page==='chat';
  const board=state.page==='dashboard'&&state.dashboardView==='map';
  const argumentChanged=render.argumentId!==state.argumentId;
  const activeElement=document.activeElement;
  const focusId=activeElement?.id;
  const selection=typeof activeElement?.selectionStart==='number'?[activeElement.selectionStart,activeElement.selectionEnd]:null;
  const scrollPositions=routeChanged?[]:[...document.querySelectorAll('[data-scroll]')].map(el=>[el.dataset.scroll,el.scrollTop]);
  const paint=()=>{
    document.body.classList.toggle('planning-screen',planning);
    $('#app').innerHTML=`<div class="shell ${planning?'planning-shell':''}"><header class="topbar"><div class="header-left"><button class="logo" data-action="navigate" data-page="home" aria-label="DPrism — về trang chủ"><span class="logo-mark"></span><span>DPrism</span></button>${state.page!=='home'?btn(ico('home')+' <span>Về trang chủ</span>','navigate','small home-return','data-page="home"'):''}${contextNavigation()}</div><div class="topbar-right">${prototypeMenu()}<span class="row small muted">${ico('globe')} VI</span><span class="avatar account-avatar" aria-label="Tran">TR</span></div></header><main class="main ${planning?'planning-main':''} ${board?'board-main':''} ${state.page==='chat'?'direct-main':''} ${routeChanged?'route-enter':''}" id="main-content">${renderPage()}</main></div>`;
    renderTools();
    for(const [key,top] of scrollPositions){const el=document.querySelector(`[data-scroll="${key}"]`);if(el)el.scrollTop=selectedChanged&&key==='node-details'||argumentChanged&&key==='argument-detail'?0:top;}
    if(focusId&&!routeChanged){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(selection&&el.setSelectionRange)try{el.setSelectionRange(...selection);}catch{}}}
    render.resizeObserver?.disconnect();
    if(planning){syncDAG();syncArgumentMap();requestAnimationFrame(()=>{const viewport=$('#dag-viewport')||$('#argument-viewport');if(window.ResizeObserver&&viewport){render.resizeObserver=new ResizeObserver(board?syncArgumentMap:syncDAG);render.resizeObserver.observe(viewport);}const detail=$('.node-detail-body');if(selectedChanged&&detail&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)detail.animate?.([{opacity:.35,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:190,easing:'ease-out'});});}
    if(state.page==='chat'){const chat=currentDirectChat();if(routeChanged||render.chatMessageCount!==chat?.messages.length||render.chatPending!==chat?.pending){const messages=$('#chat-messages');if(messages)messages.scrollTop=messages.scrollHeight;}render.chatMessageCount=chat?.messages.length;render.chatPending=chat?.pending;}
    if(routeChanged)window.scrollTo(0,0);
    render.route=route;render.selectedStep=selectedId;render.argumentId=state.argumentId;
  };
  if(routeChanged&&render.route&&document.startViewTransition&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){render.transition?.skipTransition();render.transition=document.startViewTransition(paint);}else paint();
}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><div class="between"><h1>${title}</h1>${action}</div>${description?`<p>${description}</p>`:''}</div>`;}
function renderPage(){
  if(state.page==='home')return renderHome();
  if(state.page==='experts')return renderExperts();
  if(state.page==='expert')return renderExpertPage();
  if(state.page==='direct-picker')return renderDirectPicker();
  if(state.page==='chat')return renderDirectChat();
  if(state.page==='cases')return renderCases();
  if(state.page==='templates')return renderTemplates();
  if(state.page==='setup')return renderSetup();
  if(state.page==='running')return renderRunning();
  if(state.page==='dashboard')return state.dashboardView==='report'?renderReportDashboard():renderDiscussionDashboard();
  return renderCases();
}
function renderHome(){return `<div class="welcome"><div class="welcome-intro"><div class="eyebrow">EXPERTISE, WORKING TOGETHER</div><h1>Chào Tran, hôm nay bạn muốn làm gì?</h1><p>Tạo expert theo cách bạn cần. Kết hợp chuyên môn thành một plan rõ ràng.</p></div><div class="grid2"><section class="card welcome-card"><div class="big-icon">${ico('expert')}</div><h2>Tạo chuyên gia AI</h2><p>Định nghĩa chuyên môn, cách tư duy và skills. Khám phá hoặc điều chỉnh các expert bạn đã tạo.</p><div class="row wrap">${badge('Vai trò chuyên môn')}${badge('System instructions')}${badge('Skills')}</div>${btn('Khám phá & tạo expert '+ico('arrow'),'navigate','primary','data-page="experts"')}</section><section class="card welcome-card"><div class="big-icon">${ico('chat')}</div><h2>Cùng expert giải quyết vấn đề</h2><p>Tạo case mới hoặc tham khảo case cũ. Thiết kế plan, kết hợp các expert và nhận kết quả có thể truy nguồn.</p><div class="row wrap">${badge('Plan có cấu trúc')}${badge('Case đã chia sẻ')}</div>${btn('Khám phá & tạo case '+ico('arrow'),'navigate','primary','data-page="cases"')}</section></div><div class="welcome-foot">${experts.length} expert sẵn sàng · ${templates.length} template mẫu · dữ liệu chỉ nằm trong phiên trình duyệt</div></div>`;}
function stepper(){if(state.mode==='template')return `<nav class="template-stepper" aria-label="Template đã chọn"><span class="row">${ico('check')} Template đã chọn</span><span>→</span><strong>Review plan & start</strong></nav>`;return `<nav class="stepper" aria-label="Các bước chuẩn bị">${['Bối cảnh','Case liên quan','Plan & đầu ra','Review & start'].map((s,i)=>`${i?'<div class="stepper-line"></div>':''}<button class="stepper-item ${state.wizard===i+1?'active':state.wizard>i+1?'complete':''}" data-action="wizard-goto" data-step="${i+1}" ${i+1>state.wizard?'disabled':''}><span class="step-dot">${i+1<state.wizard?'✓':i+1}</span><span>${s}</span></button>`).join('')}</nav>`;}
function wizardFooter(back,next,action='wizard-next'){return `<div class="wizard-foot">${btn(ico('back')+' '+back,'wizard-back')}<span class="muted small">${state.mode==='open'?'Plan riêng · không bắt buộc lưu template':'Bản riêng của discussion · template gốc không đổi'}</span>${btn(next+' '+ico('arrow'),action,'primary')}</div>`;}
function renderSetup(){return '<div class="setup-stepper">'+stepper()+'</div>'+(state.mode==='template'?renderPlan():state.wizard===1?renderContext():state.wizard===2?renderSimilar():state.wizard===3?renderPlan():renderReview());}
function renderContext(){
  const starFields=[['situation','S','Situation','Bối cảnh hiện tại là gì?'],['task','T','Task','Bạn cần giải quyết hoặc quyết định gì?'],['action','A','Action','Đã thử gì? Có lựa chọn và ràng buộc nào?'],['result','R','Result','Đầu ra và tiêu chí thành công là gì?']];
  return heading('01 / CONTEXT','Mô tả vấn đề','Hồ sơ rõ ràng giúp expert phân biệt dữ kiện, giả định và thông tin còn thiếu.')+`<section class="card"><div class="field"><label class="label" for="discussion-title">Tên discussion</label><input id="discussion-title" data-field="title" value="${esc(state.title)}"></div>${starFields.map(([key,letter,title,desc])=>`<div class="star-field"><span class="star-letter">${letter}</span><div><h3>${title}</h3><p>${desc}</p></div><textarea id="star-${key}" data-star="${key}" aria-label="${title}">${esc(state.star[key])}</textarea></div>`).join('')}<div class="field"><label class="label" for="initial-output">Đầu ra mong muốn</label><textarea id="initial-output" data-field="output">${esc(state.output)}</textarea></div><div class="divider"></div><div class="between section-title"><h3>Tài liệu hồ sơ</h3><span class="small muted">Gán tài liệu cho từng bước tại màn Plan</span></div><div class="row wrap">${state.discussionDocs.map(id=>docChip(id)).join('')}</div><div class="upload-zone tiny-gap"><label class="label" for="document-upload">${ico('file')} Thêm tài liệu từ máy</label><input id="document-upload" type="file" accept=".txt,.md,.pdf,.docx,.csv" multiple><p class="muted small tiny-gap">TXT/MD/CSV được đọc cục bộ; PDF/DOCX chỉ minh họa tên file, chưa trích xuất nội dung.</p></div>${wizardFooter('Chọn cách bắt đầu','Tiếp tục')}</section>`;
}
function docChip(id){const d=currentDocument(id);return d?`<span class="doc-chip">${ico('file')} ${esc(d.name)}<button class="text-button" data-action="document" data-id="${d.id}" aria-label="Xem ${esc(d.name)}">Xem</button></span>`:'';}
function renderSimilar(){return heading('02 / RELATED CASES','Không bắt đầu từ một trang trắng.','Chỉ hiển thị case đã được chủ sở hữu chia sẻ. Chọn case để đưa vào context; có thể bỏ qua bước này.')+`<div class="notice section-title"><strong>Vấn đề của bạn:</strong> ${esc(state.star.task)}</div><div class="stack">${cases.filter(c=>c.public).map(c=>`<article class="card case-card ${state.selectedCases.includes(c.id)?'selected':''}"><div class="case-check">${state.selectedCases.includes(c.id)?'✓':''}</div><div class="grow"><div class="row wrap">${badge('Đã chia sẻ toàn bộ','green')}${badge('AutoSupport')}</div><h3 class="tiny-gap">${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="case-meta">${esc(c.owner)} · ${c.date}</div></div><div class="stack" style="gap:8px">${btn('Xem toàn bộ case','case','small',`data-id="${c.id}"`)}${btn(state.selectedCases.includes(c.id)?'Đã chọn ✓':'Dùng làm context','toggle-case',state.selectedCases.includes(c.id)?'small subtle':'small primary',`data-id="${c.id}"`)}</div></article>`).join('')}</div><div class="notice gap">Case được chọn là tài liệu tham khảo từ phiên trước. Trong cùng một bước mới, các expert vẫn đưa ra đánh giá ban đầu độc lập.</div>${wizardFooter('Bối cảnh',state.mode==='open'?'Xem plan đề xuất':'Cấu hình plan')}`;}

function validatePlan(){
  if(!state.title.trim()||!state.output.trim())return 'Cần tên discussion và đầu ra mong muốn.';
  if(!state.steps.length)return 'Plan cần ít nhất một bước.';
  const ids=new Set(state.steps.map(s=>s.id));
  for(const s of state.steps){if(!s.title.trim()||!s.output.trim()||!s.experts.length)return `${s.id}: cần tên bước, đầu ra và ít nhất một expert.`;if(s.depends.some(id=>!ids.has(id)||id===s.id))return `${s.id}: phụ thuộc không hợp lệ.`;if(s.experts.length>1&&s.rounds<1)return `${s.id}: cần ít nhất một vòng trao đổi tối đa khi có nhiều expert.`;if(!Number.isInteger(s.rounds)||s.rounds<0||s.rounds>5||!Number.isFinite(s.budget)||s.budget<100)return `${s.id}: vòng trao đổi phải từ 0–5; token budget ít nhất 100.`;}
  const visiting=new Set(),visited=new Set();
  function visit(id){if(visiting.has(id))return false;if(visited.has(id))return true;visiting.add(id);for(const dep of stepById(id).depends)if(!visit(dep))return false;visiting.delete(id);visited.add(id);return true;}
  return state.steps.every(s=>visit(s.id))?'':'Phụ thuộc tạo thành chu trình. Hãy bỏ một liên kết trước khi tiếp tục.';
}
function planDepths(steps=state.steps){const depths={};function depth(s,path=[]){if(path.includes(s.id))return 0;if(depths[s.id]!==undefined)return depths[s.id];return depths[s.id]=s.depends.length?1+Math.max(...s.depends.map(id=>{const dep=steps.find(s=>s.id===id);return dep?depth(dep,[...path,s.id]):0;})):0;}steps.forEach(s=>depth(s));return depths;}
function renderDAG({runtime=false}={}){
  const steps=runtime?state.run.plan.steps:state.steps;
  const depths=planDepths(steps),groups={};steps.forEach(s=>(groups[depths[s.id]]??=[]).push(s));
  const maxDepth=Math.max(0,...Object.values(depths)),maxRows=Math.max(1,...Object.values(groups).map(g=>g.length));
  const width=Math.max(450,(maxDepth+1)*224+24),height=Math.max(150,maxRows*110+24),positions={};
  Object.entries(groups).forEach(([depth,steps])=>steps.forEach((s,i)=>positions[s.id]={x:20+Number(depth)*224,y:(height-steps.length*110)/2+i*110+10}));
  const edges=steps.flatMap(s=>s.depends.map(dep=>{const a=positions[dep],b=positions[s.id];if(!a||!b)return '';const x=a.x+180,y=a.y+44,x2=b.x,y2=b.y+44;return `<path class="${runtime&&state.run.taskStates[dep]==='DONE'?'edge-done':''}" d="M${x},${y} C${x+32},${y} ${x2-32},${y2} ${x2},${y2}" fill="none" stroke="#b3c0d2" stroke-width="1.6" marker-end="url(#dag-arrow)"/>`;})).join('');
  return `<section class="card plan-canvas ${runtime?'runtime-canvas':''}"><div class="canvas-toolbar"><strong class="row">${ico('graph')} ${runtime?'Live DAG':'Tasks'} <span class="muted small">${steps.length}</span></strong><div class="row"><div class="graph-controls">${btn('−','dag-out','small icon-btn','aria-label="Thu nhỏ DAG"')}<span id="dag-zoom">100%</span>${btn('+','dag-in','small icon-btn','aria-label="Phóng to DAG"')}${btn('Fit','dag-fit','small')}</div>${runtime?badge('3s / task','green'):btn(ico('plus')+' Thêm bước','add-step','small')}</div></div><div class="dag-viewport" id="dag-viewport" aria-label="DAG tương tác: kéo nền để di chuyển; dùng nút phóng to hoặc Fit"><div class="dag-scene" id="dag-scene" data-width="${width}" data-height="${height}" style="width:${width}px;height:${height}px"><svg class="edges" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" aria-label="Các liên kết phụ thuộc"><defs><marker id="dag-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7z" fill="#b3c0d2"/></marker></defs>${edges}</svg>${steps.map(s=>{const status=runtime?state.run.taskStates[s.id]:null,selected=s.id===(runtime?state.run.selectedStep:state.selectedStep);return `<button class="dag-node ${selected?'selected':''} ${runtime?'task-'+status.toLowerCase():''}" style="left:${positions[s.id].x}px;top:${positions[s.id].y}px" data-action="${runtime?'select-run-step':'select-step'}" data-id="${s.id}" aria-pressed="${selected}" aria-controls="node-details"><div class="between"><span class="node-number">${s.id}</span><span class="node-kind">${runtime?taskLabels[status]:s.experts.length>1?'Multi-expert':'Single expert'}</span></div><h3 title="${esc(s.title)}">${esc(s.title)}</h3><div class="node-meta">${runtime?`<span class="task-state-dot">${status==='DONE'?'✓':status==='PENDING'?'·':'↻'}</span><span>${status==='DONE'?'Đã tạo brief':status==='PENDING'?'Chờ lượt thực hiện':'Đang xử lý context'}</span>`:`${miniatureExperts(s.experts)}<span>${s.experts.length} expert · ${s.rounds} vòng</span>`}</div></button>`;}).join('')}</div></div><div class="canvas-legend"><span><i></i> ${runtime?'Đang xem task':'Bước đang chọn'}</span><span>${runtime?'● Đang chạy · ✓ Hoàn tất':'→ Phụ thuộc kết quả upstream'}</span><span class="graph-hint">Kéo nền để di chuyển · cuộn để zoom</span></div></section>`;
}
function syncDAG(){
  const viewport=$('#dag-viewport'),scene=$('#dag-scene');if(!viewport||!scene)return;
  const view=currentGraphView();
  if(view.auto){const width=Number(scene.dataset.width),height=Number(scene.dataset.height);view.zoom=Math.min(1.1,Math.max(.15,Math.min((viewport.clientWidth-24)/width,(viewport.clientHeight-18)/height)));view.x=(viewport.clientWidth-width*view.zoom)/2;view.y=(viewport.clientHeight-height*view.zoom)/2;}
  scene.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.zoom})`;
  const label=$('#dag-zoom');if(label)label.textContent=Math.round(view.zoom*100)+'%';
}
function zoomDAG(factor){const v=$('#dag-viewport');if(!v)return;const view=currentGraphView(),previous=view.zoom,next=Math.max(.2,Math.min(2,previous*factor));view.x=v.clientWidth/2-(v.clientWidth/2-view.x)*next/previous;view.y=v.clientHeight/2-(v.clientHeight/2-view.y)*next/previous;view.zoom=next;view.auto=false;syncDAG();}
function renderNodeDetails(){
  const s=stepById(state.selectedStep)||state.steps[0];if(!s)return '';
  return `<section class="card node-details" id="node-details" aria-labelledby="node-details-title"><header class="node-detail-header"><div class="row"><span class="task-icon">${ico('plan')}</span><div><h3 id="node-details-title">${esc(s.title)}</h3><span class="small muted">${s.id} · Cấu hình task</span></div></div>${btn(ico('close')+' Xóa bước','remove-step','small',`data-id="${s.id}" ${state.steps.length===1?'disabled':''}`)}</header><div class="node-detail-body" data-scroll="node-details"><div class="node-config-grid"><div class="node-config-section"><div class="field"><label class="label" for="step-title">Tên bước</label><input id="step-title" data-step-field="title" value="${esc(s.title)}"></div><div class="field"><label class="label" for="step-instruction">Yêu cầu thực hiện</label><textarea id="step-instruction" data-step-field="instruction">${esc(s.instruction)}</textarea></div><div class="field"><label class="label" for="step-output">Đầu ra của bước</label><textarea id="step-output" data-step-field="output">${esc(s.output)}</textarea></div><div class="inspector-group"><h3>Phụ thuộc</h3>${state.steps.filter(other=>other.id!==s.id).map(other=>`<label class="check"><input type="checkbox" data-step-list="depends" value="${other.id}" ${s.depends.includes(other.id)?'checked':''}>${other.id} · ${esc(other.title)}</label>`).join('')||'<p class="small muted">Không có bước khác.</p>'}</div></div><div class="node-config-section"><h3>Expert được giao</h3><div class="tiny-gap">${experts.map(e=>`<label class="expert-option">${avatar(e)}<span>${esc(e.role)}</span><input type="checkbox" data-step-list="experts" value="${e.id}" ${s.experts.includes(e.id)?'checked':''}></label>`).join('')}</div><div class="inspector-group"><h3>Giới hạn thực hiện</h3><div class="two-fields"><label><span class="label">Vòng trao đổi tối đa</span><input type="number" id="step-rounds" data-step-field="rounds" min="0" max="5" value="${s.rounds}"></label><label><span class="label">Token / task</span><input type="number" id="step-budget" data-step-field="budget" min="100" step="1000" value="${s.budget}"></label></div><p class="small muted tiny-gap">Đánh giá đầu tiên độc lập, sau đó tối đa ${s.rounds} vòng phản biện. Không bắt buộc đồng thuận.</p></div></div><div class="node-config-section"><h3>Tài liệu riêng của bước</h3><div class="tiny-gap">${documents.map(d=>`<div class="between"><label class="check"><input type="checkbox" data-step-list="docs" value="${d.id}" ${s.docs.includes(d.id)?'checked':''}>${esc(d.name)}</label><button class="text-button" data-action="document" data-id="${d.id}">Xem</button></div>`).join('')}</div><div class="inspector-group"><h3>Context expert sẽ nhận</h3><div class="input-preview">• Vấn đề và đầu ra discussion<br>• Chỉ dẫn của task và skills của expert<br>• ${s.docs.length} tài liệu riêng + ${state.discussionDocs.length} tài liệu hồ sơ<br>• ${s.depends.length?'Brief từ '+s.depends.join(', '):'Không có brief upstream'}<br>• ${state.selectedCases.length} case đã chọn<br>• Ý kiến peer chỉ được cấp ở pha phản biện</div></div></div></div></div></section>`;
}
function renderJobInfo(){
  return `<aside class="card job-info" aria-labelledby="job-info-title"><header class="job-info-header"><div class="eyebrow">DISCUSSION PLAN</div><h3 id="job-info-title">Thông tin chung</h3></header><div class="job-info-body" data-scroll="job-info"><div class="row wrap">${badge(state.mode==='open'?'Plan đề xuất':'Từ template','red')}${badge('Bản nháp')}</div><div class="field gap"><label class="label" for="job-title">Tên plan</label><input id="job-title" data-field="title" value="${esc(state.title)}"></div><div class="job-metrics"><div><strong>${state.steps.length}</strong><span>Tasks</span></div><div><strong>${selectedExpertCount()}</strong><span>Experts</span></div><div><strong>${state.selectedCases.length}</strong><span>Cases</span></div></div><div class="inspector-group"><label class="label" for="plan-output">Đầu ra cuối cùng</label><textarea id="plan-output" data-field="output">${esc(state.output)}</textarea></div><div class="inspector-group"><h3>Tài liệu hồ sơ chung</h3><div class="stack tiny-gap" style="gap:8px">${state.discussionDocs.map(docChip).join('')||'<span class="small muted">Chưa có tài liệu.</span>'}</div><button class="text-button tiny-gap" data-action="wizard-goto" data-step="1">Chỉnh bối cảnh & tài liệu →</button></div><div class="inspector-group"><h3>Case tham khảo</h3><p class="small muted tiny-gap">${state.selectedCases.length?state.selectedCases.map(id=>esc(cases.find(c=>c.id===id)?.title||id)).join('<br>'):'Chưa chọn case tham khảo.'}</p><button class="text-button tiny-gap" data-action="wizard-goto" data-step="2">Chọn case liên quan →</button></div><div class="inspector-group"><h3>Quy tắc kết thúc</h3><ul class="job-policy"><li>Trao đổi theo giới hạn của từng task.</li><li>Giữ nguyên các ý kiến còn khác nhau.</li><li>Thoát rõ trạng thái nếu không thể tiếp tục.</li><li>Không chỉnh plan sau Start.</li></ul></div>${btn(ico('plus')+' Lưu thành template mới','save-template','small','style="width:100%"')}<div class="notice tiny-gap">Chỉnh bản plan này không thay đổi template gốc.</div></div></aside>`;
}
function renderPlan(){const final=state.mode==='template';return `<div class="planning-title"><div><div class="eyebrow">${final?'TEMPLATE / FINAL REVIEW':'03 / PLAN DESIGN'}</div><h1>${final?'Review plan & start':'Thiết kế plan'}</h1></div><span class="muted small">${final?'Chỉnh task, context và đầu ra, rồi bắt đầu ngay.':'Chọn một task trên DAG để chỉnh cấu hình bên dưới.'}</span></div><div class="planning-workspace"><div class="job-left">${renderDAG()}${renderNodeDetails()}</div>${renderJobInfo()}</div><footer class="planning-footer"><button class="btn" data-action="${final?'navigate':'wizard-back'}" ${final?'data-page="templates"':''}>${ico('back')} ${final?'Chọn template khác':'Case liên quan'}</button><div class="planning-feedback ${state.validation?'invalid':''}" role="status">${state.validation?esc(state.validation):'Plan được cố định sau Start. Các thay đổi hiện tại chỉ áp dụng cho phiên này.'}</div>${btn((final?'Start discussion':'Review plan')+' '+ico('arrow'),final?'start':'wizard-next','primary')}</footer>`;}
function renderReview(){const refs=[...new Set(state.steps.flatMap(s=>s.docs))];return heading('04 / READY TO START','Kiểm tra lần cuối.','Plan sẽ được cố định khi bắt đầu. Chỉ expert AI tham gia thực hiện.')+`<div class="review-layout"><div class="review-list">${[
  ['file','Vấn đề & đầu ra',`${state.title}\n${state.output}`,1],
  ['book','Case tham khảo',state.selectedCases.length?state.selectedCases.map(id=>cases.find(c=>c.id===id)?.title).filter(Boolean).join(' · '):'Không dùng case tham khảo',2],
  ['graph','Plan & phân công',`${state.steps.length} bước · ${selectedExpertCount()} expert · ${refs.length} tài liệu tham khảo riêng theo bước`,3]
].map(([icon,title,description,step])=>`<section class="card review-row"><span class="avatar">${ico(icon)}</span><div class="grow"><h3>${title}</h3><p>${esc(description)}</p></div><button class="text-button" data-action="wizard-goto" data-step="${step}">Chỉnh sửa</button></section>`).join('')}<section class="card"><div class="between section-title"><h3>Trình tự thực hiện</h3>${badge('Không sửa khi đang chạy')}</div>${state.steps.map(s=>`<div class="between" style="padding:11px 0;border-bottom:1px solid var(--line)"><div class="row"><span class="section-number">${s.id.slice(1)}</span><div><h3 class="small">${esc(s.title)}</h3><p class="muted" style="font-size:10px">${s.depends.length?'Sau '+s.depends.join(', '):'Không phụ thuộc'} · ${s.experts.length} expert · tối đa ${s.rounds} vòng trao đổi</p></div></div>${miniatureExperts(s.experts)}</div>`).join('')}</section></div><aside class="card review-side"><div class="eyebrow">EXECUTION CONTRACT</div><h3>Điểm kết thúc rõ ràng</h3><ul><li>Dừng trao đổi khi đạt giới hạn của từng bước.</li><li>Giữ nguyên các ý kiến còn khác nhau.</li><li>Nếu không thể tiếp tục, giữ kết quả đã có và chỉ rõ phần chưa hoàn tất.</li><li>Không chờ người phân xử hoặc thêm vòng trong lúc chạy.</li></ul><div class="notice amber">Trong prototype, Start mở luồng màn hình mẫu; không chạy model hoặc LangGraph.</div>${state.validation?`<div class="plan-error">${esc(state.validation)}</div>`:''}${btn('Start discussion '+ico('arrow'),'start','primary gap','style="width:100%"')}</aside></div>${wizardFooter('Plan & đầu ra','Start discussion','start')}`;}

const sampleResults={
  C1:{rating:'HIGH',summary:'Nội dung truy xuất chưa có ranh giới tin cậy rõ ràng; cần kiểm soát prompt injection trước pilot.',dissent:'Security Expert giữ mức HIGH; AI Safety Expert cho rằng MODERATE phù hợp nếu bật kiểm soát nội dung. Bằng chứng triển khai kiểm soát chưa có.',evidence:[{doc:'D1',ref:'§1',quote:'Hệ thống nhận nội dung từ khách hàng và tài liệu đính kèm.'},{doc:'D2',ref:'§1',quote:'Nội dung không tin cậy không được thay đổi chính sách hoặc quyền thực thi.'}]},
  C2:{rating:'MODERATE',summary:'Cần bổ sung chính sách che dữ liệu khi logging và thời gian lưu giữ hồ sơ.',dissent:'Chưa có bất đồng trọng yếu trong dữ liệu mẫu.',evidence:[{doc:'D1',ref:'§2',quote:'Kết quả truy vấn có thể chứa dữ liệu nhận diện khách hàng.'},{doc:'D3',ref:'§2',quote:'Che dữ liệu nhạy cảm trước khi ghi log.'}]},
  C3:{rating:'HIGH',summary:'Service account dùng chung chưa thể hiện phân quyền theo người dùng cuối.',dissent:'Hai expert giữ mức HIGH; khác nhau về ưu tiên giảm thiểu.',evidence:[{doc:'D1',ref:'§3',quote:'Công cụ tra cứu hiện dùng service account có quyền dùng chung.'},{doc:'D2',ref:'§2',quote:'Quyền truy cập công cụ phải gắn với người dùng cuối.'}]},
  C4:{rating:'HIGH',summary:'Chỉ nên pilot sau khi bổ sung kiểm soát nội dung, phân quyền công cụ và xử lý dữ liệu.',dissent:'Bảo tồn bất đồng về C1 trong báo cáo; đây là kết luận AI mẫu, chưa được người thật phê duyệt.',evidence:[{doc:'D2',ref:'§3',quote:'Mỗi đánh giá phải có bằng chứng, giới hạn và biện pháp giảm thiểu.'}]}
};
function buildResult(step,index,run=state.run){
  const original=templateSteps().find(s=>s.id===step.id);
  const baseline=run?.plan.templateId==='ai-risk'&&original&&['title','instruction','output','experts','docs','depends'].every(key=>JSON.stringify(step[key])===JSON.stringify(original[key]));
  const sample=baseline?clone(sampleResults[step.id]):{rating:null,summary:'Đầu ra minh họa cho bước đã cấu hình. Prototype chưa sinh nội dung theo chỉ dẫn mới.',dissent:step.experts.length>1?'Có thể hiển thị các quan điểm khác nhau tại đây; chưa đánh giá thực tế.':'Một expert thực hiện; không có phản biện chéo.',evidence:[]};
  const permitted=new Set([...step.docs,...run.plan.discussionDocs]);
  sample.evidence=sample.evidence.filter(e=>permitted.has(e.doc));
  return {stepId:step.id,title:step.title,outputContract:step.output,...sample,rounds:step.rounds,experts:step.experts.map((id,i)=>({id,role:run.plan.experts.find(e=>e.id===id)?.role||id,initial:baseline&&step.id==='C1'&&id==='safety'?'MODERATE':sample.rating,final:baseline&&step.id==='C1'&&id==='safety'?'MODERATE':sample.rating,view:i===0?'Ưu tiên bằng chứng về tác động và điều kiện kiểm soát.':'Ưu tiên các tình huống thất bại và ranh giới tin cậy.'})),index};
}
function topologicalSteps(steps){const done=new Set(),result=[];for(let i=0;i<steps.length;i++){const ready=steps.find(s=>!done.has(s.id)&&s.depends.every(id=>done.has(id)));if(!ready)break;done.add(ready.id);result.push(ready);}return result;}
function renderReportDashboard(){
  const run=state.run;if(!run)return '<div class="empty">Chưa có discussion.</div>';
  const complete=run.status==='completed',remaining=run.plan.steps.length-run.results.length;
  return '<div class="report-navigation">'+backButton('cases','Quay lại Cases')+btn(ico('graph')+' Argument map','dashboard-mode','small','data-view="map"')+'</div>'+heading('DISCUSSION / RESULTS',esc(run.plan.title),'Kết quả minh họa theo plan đã review. Mỗi kết luận có thể mở xuống ý kiến expert và tài liệu liên quan.',`<div class="row">${btn(ico('download')+' Xuất kết quả','export','small')}${btn(ico('link')+' Chia sẻ','share','small')}</div>`)+`<div class="notice ${complete?'green':'amber'}"><strong>${complete?'Plan đã hoàn tất':'Plan chưa hoàn tất'}</strong> · ${complete?'Các bất đồng được giữ nguyên; không đồng nghĩa với phê duyệt của người thật.':esc(run.exit.reason)} <span class="badge ${complete?'green':'amber'}">DỮ LIỆU MẪU</span></div><div class="metric-grid"><div class="card metric"><span class="label">Bước hoàn tất</span><strong>${run.results.length}<span class="muted" style="font-size:16px"> / ${run.plan.steps.length}</span></strong><span class="small muted">${remaining?remaining+' bước chưa thực hiện':'Đã đến điểm kết thúc'}</span></div><div class="card metric"><span class="label">Expert trong plan</span><strong>${new Set(run.plan.steps.flatMap(s=>s.experts)).size}</strong><span class="small muted">AI expert · theo phân công</span></div><div class="card metric"><span class="label">Thời gian mô phỏng</span><strong>${elapsedLabel(run.durationMs||0)}</strong><span class="small muted">3 giây cho mỗi task · không gọi model</span></div><div class="card metric"><span class="label">Nguồn được trích dẫn</span><strong>${new Set(run.results.flatMap(r=>r.evidence.map(e=>e.doc))).size}</strong><span class="small muted">Có thể mở tài liệu gốc</span></div></div>${renderDashboardInsights(run)}<nav class="dashboard-tabs" aria-label="Nội dung kết quả">${[['overview','Tổng quan'],['results','Kết quả từng bước'],['evidence','Bằng chứng'],['trace','Trace thực hiện'],['plan','Plan đã chạy']].map(([key,label])=>`<button class="tab ${state.dashTab===key?'active':''}" data-action="dash-tab" data-tab="${key}">${label}</button>`).join('')}</nav>${state.dashTab==='overview'?renderOverview():state.dashTab==='results'?renderResultTable():state.dashTab==='evidence'?renderEvidence():state.dashTab==='trace'?renderTrace():renderRunPlan()}`;
}
function renderOverview(){const run=state.run;return `<div class="review-layout"><div class="stack"><section class="card"><div class="eyebrow">EXECUTIVE SUMMARY · SAMPLE</div><h2>${run.status==='completed'?'Bức tranh tổng thể, với các ý kiến được giữ nguyên.':'Kết quả đến thời điểm thoát.'}</h2><p class="small muted gap">${run.results.length?esc(run.results.at(-1).summary):'Chưa có bước nào hoàn tất. Không có kết luận nghiệp vụ để sử dụng.'}</p>${run.exit?`<div class="notice amber gap">Chưa thực hiện: ${run.exit.unexecuted.map(id=>esc(run.plan.steps.find(s=>s.id===id)?.title||id)).join(', ')}. Không suy diễn kết luận cho các bước này.</div>`:''}<div class="divider"></div><h3>Các phát hiện đã ghi nhận</h3>${run.results.map(r=>`<div class="finding"><div class="between"><h3>${r.stepId} · ${esc(r.title)}</h3>${r.rating?badge(r.rating,r.rating==='HIGH'?'red':'amber'):badge('Nội dung mẫu')}</div><p>${esc(r.summary)}</p><button class="text-button" data-action="result-detail" data-id="${r.stepId}">Xem ý kiến & bằng chứng →</button></div>`).join('')||'<p class="small muted tiny-gap">Chưa có phát hiện.</p>'}</section>${renderResultTable()}</div><aside class="stack"><section class="card"><div class="eyebrow">PRESERVE DISSENT</div><h3>Bất đồng không bị san phẳng</h3><p class="small muted tiny-gap">${esc(run.results.find(r=>r.experts.length>1)?.dissent||'Chưa có ý kiến phản biện trong phần đã thực hiện.')}</p></section><section class="card"><h3>Đầu ra đã yêu cầu</h3><p class="small muted tiny-gap">${esc(run.plan.output)}</p><div class="divider"></div><h3>Tái sử dụng</h3><p class="small muted tiny-gap">Xuất JSON để giữ plan và trace; xuất Markdown để tiếp tục biên tập báo cáo.</p>${btn(ico('download')+' Xuất file','export','small gap')}</section></aside></div>`;}
function renderResultTable(){const run=state.run;return `<section class="card"><div class="between section-title"><h3>Kết quả theo từng bước</h3><span class="small muted">Chọn dòng để truy nguồn</span></div><div class="table-scroll"><table class="report-table"><thead><tr><th>Bước</th><th>Expert</th><th>Kết quả</th><th>Trạng thái</th></tr></thead><tbody>${run.plan.steps.map(s=>{const r=run.results.find(r=>r.stepId===s.id);return `<tr tabindex="0" data-action="${r?'result-detail':'unexecuted'}" data-id="${s.id}"><td><strong>${s.id} · ${esc(s.title)}</strong></td><td>${miniatureExperts(s.experts)}</td><td>${r?r.rating?badge(r.rating,r.rating==='HIGH'?'red':'amber'):badge('Đầu ra minh họa'):'—'}</td><td>${badge(r?'Hoàn tất':run.exit?.step===s.id?'Dừng tại đây':'Chưa thực hiện',r?'green':'amber')}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function renderEvidence(){const all=state.run.results.flatMap(r=>r.evidence.map(e=>({...e,step:r.stepId})));return `<section class="card"><h3>Bằng chứng được dẫn trong kết quả mẫu</h3>${all.map(e=>`<div class="evidence-row"><div class="between"><span class="row">${badge(e.step)}<strong class="small">${esc(currentDocument(e.doc)?.name)} · ${esc(e.ref)}</strong></span>${btn('Mở nguồn '+ico('arrow'),'document','small',`data-id="${e.doc}"`)}</div><p>“${esc(e.quote)}”</p></div>`).join('')||'<div class="empty">Chưa có trích dẫn. Prototype không tự tạo bằng chứng cho bước bạn vừa thêm hoặc chỉnh.</div>'}</section>`;}
function renderTrace(){return `<section class="card"><div class="between section-title"><h3>Lịch sử thực hiện</h3>${badge('Event mẫu · không phải log backend')}</div>${state.run.trace.map(t=>`<div class="trace-entry"><time>${t.time}</time><span class="trace-dot"></span><div><strong>${esc(t.title)}</strong><p>${esc(t.detail)}</p>${t.step?`<button class="text-button" data-action="result-detail" data-id="${t.step}">Mở artifact ${t.step} →</button>`:''}</div></div>`).join('')}</section>`;}
function renderRunPlan(run=state.run){return `<section class="card"><h3>Bản plan tại thời điểm Start</h3><p class="small muted tiny-gap">Các thay đổi trong discussion mới không sửa bản đã chạy.</p>${run.plan.steps.map(s=>`<article class="review-row" style="border-bottom:1px solid var(--line)"><span class="section-number">${s.id.slice(1)}</span><div class="grow"><h3>${esc(s.title)}</h3><p>${esc(s.instruction)}</p><p>${s.depends.length?'Upstream: '+s.depends.join(', '):'Không có upstream'} · ${s.rounds} vòng tối đa · ${s.budget.toLocaleString()} token/task</p><p>Đầu ra: ${esc(s.output)}</p><p>Expert: ${s.experts.map(id=>esc(run.plan.experts.find(e=>e.id===id)?.role||id)).join(', ')}</p><p>Tài liệu: ${s.docs.map(id=>esc(currentDocument(id)?.name||id)).join(', ')}</p></div></article>`).join('')}</section>`;}
function renderCases(){
  const q=state.caseQuery.toLowerCase();
  const mine=state.sessions.map((run,index)=>({run,index})).filter(({run})=>run.plan.title.toLowerCase().includes(q));
  const shared=cases.filter(c=>c.public&&(c.title+' '+c.description).toLowerCase().includes(q));
  const cards=state.caseTab==='shared'?shared.map(c=>`<article class="card stack"><div class="between">${badge('Đã chia sẻ toàn bộ','green')}<span class="muted small">${c.date}</span></div><h3>${esc(c.title)}</h3><p class="small muted">${esc(c.description)}</p><div class="notice">${esc(c.summary)}</div><div class="between"><span class="small muted">${esc(c.owner)}</span>${btn('Xem case','case','small',`data-id="${c.id}"`)}</div></article>`).join(''):mine.map(({run,index})=>`<article class="card stack"><div class="between">${badge(run.status==='running'?'Đang chạy':run.status==='completed'?'Hoàn tất':'Chưa hoàn tất',run.status==='completed'?'green':'amber')}<span class="small muted">${run.plan.steps.length} bước</span></div><h3>${esc(run.plan.title)}</h3><p class="small muted">${esc(run.plan.star.task)}</p><div class="between"><span class="small muted">${run.shared?'Đã chia sẻ':'Chỉ mình tôi'}</span>${btn(run.status==='running'?'Xem tiến trình':'Xem kết quả','session','small',`data-index="${index}"`)}</div></article>`).join('');
  const draft=state.caseTab==='mine'&&state.hasDraft&&state.title.toLowerCase().includes(q)?`<article class="card stack draft-card">${badge('Bản nháp','purple')}<h3>${esc(state.title)}</h3><p class="small muted">Tiếp tục chuẩn bị ở bước ${state.wizard} / 4. Các chỉnh sửa đang được giữ trong phiên này.</p>${btn('Tiếp tục chỉnh sửa '+ico('arrow'),'resume-draft','small')}</article>`:'';
  return heading('DISCUSSION WORKSPACE','Cùng expert giải quyết vấn đề','Tạo case mới, tiếp tục công việc của bạn hoặc tìm hiểu các case đã được chia sẻ.',btn(ico('plus')+' Tạo case mới','navigate','primary','data-page="templates"'))+`<nav class="dashboard-tabs" aria-label="Danh sách case"><button class="tab ${state.caseTab==='mine'?'active':''}" data-action="case-tab" data-tab="mine">Case của tôi ${badge(state.sessions.length+state.chats.length+(state.hasDraft?1:0))}</button><button class="tab ${state.caseTab==='shared'?'active':''}" data-action="case-tab" data-tab="shared">Case đã chia sẻ ${badge(cases.filter(c=>c.public).length)}</button></nav><div class="library-toolbar"><div class="search-box">${ico('search')}<input id="case-search" data-field="caseQuery" value="${esc(state.caseQuery)}" placeholder="Tìm case…" aria-label="Tìm case"></div><span class="small muted">${state.caseTab==='shared'?'Xem toàn bộ nội dung; có thể dùng làm context':'Bản nháp, phiên đang chạy và kết quả'}</span></div><div class="grid3">${draft+cards+renderDirectChatCaseCards()||`<section class="card empty-state"><span class="avatar">${ico('chat')}</span><h2>Case tiếp theo bắt đầu từ bạn.</h2><p>Tạo một case mới hoặc tham khảo case đã chia sẻ để tìm cách tiếp cận.</p><div class="row wrap">${btn(ico('plus')+' Tạo case mới','navigate','primary','data-page="templates"')}${btn('Tham khảo case cũ','case-tab','','data-tab="shared"')}</div></section>`}</div>`;
}
const modalHistory=[];
function openModal(title,description,content,wide=false){
  const opener=document.activeElement;
  if($('#modal-root').firstElementChild)modalHistory.push({node:$('#modal-root').firstElementChild,opener:openModal.opener});
  $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(description)}</p></div><button class="btn small icon-btn" data-action="close-modal" aria-label="Đóng">${ico('close')}</button></div>${content}</section></div>`;
  openModal.opener=opener;$('#app').inert=true;$('#prototype-tools').inert=true;
  ($('input,textarea,select', $('#modal-root'))||$('button', $('#modal-root')))?.focus();
}
function closeModal(){if(!$('#modal-root').firstChild)return;const opener=openModal.opener;if(modalHistory.length){const previous=modalHistory.pop();$('#modal-root').replaceChildren(previous.node);openModal.opener=previous.opener;opener?.focus?.();return;}$('#modal-root').innerHTML='';$('#app').inert=false;$('#prototype-tools').inert=false;opener?.focus?.();}
function resultModal(id,run=state.run){const r=run?.results.find(r=>r.stepId===id);if(!r){toast('Bước chưa có kết quả để xem.');return;}
  openModal(`${r.stepId} · ${r.title}`,'Artifact minh họa · ý kiến và trích dẫn không được sinh bởi model.',`<div class="notice">${esc(r.summary)}</div><h3 class="gap">Ý kiến expert · trước và sau phản biện</h3><div class="stack tiny-gap">${r.experts.map(e=>`<article class="card soft"><div class="between"><div class="row">${avatar(expertById(e.id))}<h3>${esc(e.role)}</h3></div><div class="row">${badge(e.initial||'Đầu ra mẫu')}<span class="muted">→</span>${badge(e.final||'Đầu ra mẫu')}</div></div><p class="small muted tiny-gap">${esc(e.view)} ${r.stepId==='C1'&&e.id==='safety'?'Giữ MODERATE với giả định kiểm soát nội dung được bật; bằng chứng xác nhận chưa có.':''}</p></article>`).join('')}</div><div class="notice amber gap"><strong>Bất đồng / giới hạn:</strong> ${esc(r.dissent)}</div><h3 class="gap">Bằng chứng liên quan</h3>${r.evidence.map(e=>`<div class="evidence-row"><button class="text-button" data-action="document" data-id="${e.doc}">${esc(currentDocument(e.doc)?.name)} · ${e.ref} ↗</button><p>“${esc(e.quote)}”</p></div>`).join('')||'<p class="small muted tiny-gap">Chưa có trích dẫn thực tế cho cấu hình này.</p>'}<div class="notice gap"><strong>Brief downstream:</strong> ${esc(r.summary)}<br><strong>Bất đồng còn mở:</strong> ${esc(r.dissent)}</div>`,true);
}
function documentModal(id){const doc=currentDocument(id);if(!doc)return;openModal(doc.name,`${doc.kind} · ${doc.id} · ${doc.metadataOnly?'chỉ có thông tin file':'nội dung mẫu / văn bản đọc cục bộ'}`,`<pre>${esc(doc.text)}</pre>`);}
function caseModal(id){const c=cases.find(c=>c.id===id);if(!c)return;if(c.run){openModal(c.title,'Case chia sẻ toàn bộ · bản frontend mẫu',`<div class="notice">${esc(c.summary)}</div><h3 class="gap">Bối cảnh</h3><p class="small muted tiny-gap">${esc(c.run.plan.star.situation)}</p><p class="small muted tiny-gap">${esc(c.run.plan.star.task)}<br>${esc(c.run.plan.star.action)}<br>${esc(c.run.plan.star.result)}</p><h3 class="gap">Đầu ra yêu cầu</h3><p class="small muted tiny-gap">${esc(c.run.plan.output)}</p><h3 class="gap">Plan và kết quả</h3>${renderRunPlan(c.run)}${c.run.results.map(r=>`<article class="card tiny-gap"><h3>${esc(r.title)}</h3><p class="small muted tiny-gap">${esc(r.summary)}</p><button class="text-button" data-action="case-result" data-case="${c.id}" data-id="${r.stepId}">Ý kiến & bằng chứng →</button></article>`).join('')}<h3 class="gap">Trace</h3><pre>${esc(JSON.stringify(c.run.trace,null,2))}</pre>${c.run.exit?`<div class="notice amber">${esc(c.run.exit.reason)}</div>`:''}<h3 class="gap">Tài liệu</h3><div class="row wrap tiny-gap">${c.docs.map(docChip).join('')}</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.selectedCases.includes(c.id)?'Bỏ khỏi context':'Dùng làm context','case-from-modal','primary',`data-id="${c.id}"`)}</div>` ,true);return;}
  openModal(c.title,'Case public · toàn bộ nội dung có sẵn trong fixture',`<div class="row">${badge('Đã chia sẻ toàn bộ','green')}${badge(c.rating,'red')}</div><div class="gap"><h3>Bối cảnh & mục tiêu</h3><p class="small muted tiny-gap">${esc(c.description)}</p></div><div class="gap"><h3>Plan đã sử dụng</h3><ol class="small muted" style="line-height:2"><li>Đánh giá độc lập hồ sơ AutoSupport.</li><li>Phản biện có giới hạn giữa Safety và Security expert.</li><li>Tổng hợp kết quả và giữ lại bất đồng.</li></ol></div><div class="gap"><h3>Kết quả</h3><p class="small muted tiny-gap">${esc(c.summary)}</p></div><div class="gap"><h3>Ý kiến & phản biện</h3><p class="small muted tiny-gap">Safety Expert: cần kiểm chứng kiểm soát nội dung. Security Expert: cần ràng buộc quyền công cụ theo người dùng. Sau phản biện, cả hai giữ yêu cầu bổ sung bằng chứng trước pilot.</p></div><div class="gap"><h3>Tài liệu nguồn</h3><div class="row wrap tiny-gap">${c.docs.map(docChip).join('')}</div></div><div class="notice gap">Trace mẫu: nạp hồ sơ → đánh giá độc lập → phản biện → tổng hợp. Đây là toàn bộ case mẫu, không có transcript ẩn.</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.selectedCases.includes(c.id)?'Bỏ khỏi context':'Dùng làm context','case-from-modal','primary',`data-id="${c.id}"`)}</div>`,true);
}
function exportObject(){return {prototype:true,execution:'frontend_fixture_only',runId:state.run.id,status:state.run.status,durationMs:state.run.durationMs||0,taskDurationMs:TASK_DURATION_MS,plan:state.run.plan,results:state.run.results,exit:state.run.exit,trace:state.run.trace,documents:documents.filter(d=>new Set([...state.run.plan.discussionDocs,...state.run.plan.steps.flatMap(s=>s.docs)]).has(d.id)),approvedByHuman:false};}
function download(format){if(!state.run)return;const data=exportObject();let text;
  if(format==='json')text=JSON.stringify(data,null,2);
  else text=`# ${data.plan.title}\n\n> FRONTEND PROTOTYPE — Dữ liệu minh họa, chưa được người thật phê duyệt.\n\nTrạng thái: ${data.status}\n\n## Đầu ra yêu cầu\n${data.plan.output}\n\n${data.exit?'## Thoát sớm\n'+data.exit.reason+'\nChưa thực hiện: '+data.exit.unexecuted.join(', ')+'\n\n':''}${data.results.map(r=>`## ${r.stepId} — ${r.title}\n${r.summary}\n\nBất đồng: ${r.dissent}\n\n${r.evidence.map(e=>`- ${e.doc}${e.ref}: ${e.quote}`).join('\n')}\n`).join('\n')}\n## Trace\n${data.trace.map(e=>`- ${e.time}: ${e.title} — ${e.detail}`).join('\n')}`;
  const url=URL.createObjectURL(new Blob([text],{type:format==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`dprism-${state.run.id}.${format==='json'?'json':'md'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất file dữ liệu mẫu.');
}
function renderTools(){
  $('#prototype-tools').innerHTML=`${state.showState?`<aside class="state-drawer"><div class="between"><h3>State frontend · chỉ trong bộ nhớ</h3><button data-action="toggle-state" aria-label="Đóng state">×</button></div><pre>${esc(JSON.stringify({...state,availableExperts:experts,availableSkills:skills,availableDocuments:documents},null,2))}</pre></aside>`:''}`;
}
function go(page){state.page=page;state.validation='';render();window.scrollTo(0,0);}
function applyTemplate(id){state.templateId=id;state.steps=id==='ai-risk'?templateSteps():[
  {id:'C1',title:'Xác định tiêu chí so sánh',depends:[],experts:['safety','operations'],rounds:1,budget:10000,docs:['D1'],instruction:'Xác định các tiêu chí và ràng buộc từ hồ sơ AutoSupport.',output:'Danh sách tiêu chí và trọng số đề xuất'},
  {id:'C2',title:'So sánh phương án kiểm soát',depends:['C1'],experts:['security','operations'],rounds:2,budget:14000,docs:['D1','D2'],instruction:'So sánh phương án kiểm soát theo các tiêu chí upstream.',output:'Ma trận phương án, bằng chứng và trade-off'},
  {id:'C3',title:'Tổng hợp khuyến nghị',depends:['C2'],experts:['synthesizer'],rounds:0,budget:8000,docs:['D1'],instruction:'Tổng hợp lựa chọn, giới hạn và quan điểm khác nhau.',output:'Khuyến nghị và điều kiện thực hiện'}
];state.selectedStep='C1';state.output=id==='ai-risk'?'Bảng rủi ro theo cấu phần; executive summary; bằng chứng; bất đồng; biện pháp giảm thiểu; trace thực hiện.':'Ma trận so sánh phương án, trade-off, khuyến nghị và điều kiện triển khai.';}
function startNew(mode,templateId){state.mode=mode;state.wizard=mode==='template'?4:1;state.hasDraft=true;state.validation='';state.dagView.auto=true;if(templateId)applyTemplate(templateId);else state.templateId=null;go('setup');}
function handleAction(button){const action=button.dataset.action,id=button.dataset.id;
  if(handleDiscussionAction(button))return;
  if(action==='navigate')return go(button.dataset.page);
  if(action==='case-tab'){state.caseTab=button.dataset.tab;render();return;}
  if(action==='resume-draft')return go('setup');
  if(action==='new-expert'||action==='expert-profile')return openExpert(id);
  if(action==='edit-expert'){state.expertEditing=true;render();return;}
  if(action==='cancel-expert'){if(state.expertId)return openExpert(state.expertId);return go('experts');}
  if(action==='close-modal')return closeModal();
  if(action==='skill'){const s=skills.find(s=>s.name===button.dataset.name);return openModal(s.name,'SKILL.md mẫu · chỉ để đọc trong prototype',`<pre>${esc(s.content)}</pre>`);}
  if(action==='use-template')return startNew('template',id);
  if(action==='open-discussion'){startNew('open');state.templateId=null;return;}
  if(action==='wizard-next'){
    if(state.wizard===1&&(!state.title.trim()||!state.star.task.trim()||!state.output.trim()))return toast('Cần tên discussion, mục tiêu và đầu ra mong muốn.');
    if(state.wizard===2&&state.mode==='open'){
      const desiredOutput=state.output;applyTemplate('ai-risk');state.templateId=null;state.output=desiredOutput;toast('Plan đề xuất là fixture; chưa có AI phân tích chủ đề.');
    }
    if(state.wizard===3){state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}}
    state.wizard=Math.min(4,state.wizard+1);render();window.scrollTo(0,0);return;
  }
  if(action==='wizard-back'){if(state.wizard===1)return go('templates');state.wizard--;render();window.scrollTo(0,0);return;}
  if(action==='wizard-goto'){if(state.mode==='template')return templateInputsModal(Number(button.dataset.step)===2?'cases':'context');state.wizard=Number(button.dataset.step);render();window.scrollTo(0,0);return;}
  if(action==='toggle-case'||action==='case-from-modal'){state.selectedCases=state.selectedCases.includes(id)?state.selectedCases.filter(x=>x!==id):[...state.selectedCases,id];if(action==='case-from-modal')closeModal();render();return;}
  if(action==='case')return caseModal(id);
  if(action==='case-result')return resultModal(id,cases.find(c=>c.id===button.dataset.case)?.run);
  if(action==='document')return documentModal(id);
  if(action==='select-step'){state.selectedStep=id;state.validation='';render();return;}
  if(action==='select-run-step'){state.run.selectedStep=id;state.run.followActive=false;render();return;}
  if(action==='follow-task'){state.run.followActive=true;state.run.selectedStep=state.run.activeStep;render();return;}
  if(action==='add-step'){const id='C'+(Math.max(0,...state.steps.map(s=>Number(s.id.slice(1))))+1);state.steps.push({id,title:'Bước mới',depends:state.steps.length?[state.steps.at(-1).id]:[],experts:[],rounds:1,budget:10000,docs:[],instruction:'',output:''});state.selectedStep=id;state.dagView.auto=true;render();return;}
  if(action==='remove-step'){state.steps=state.steps.filter(s=>s.id!==id);state.steps.forEach(s=>s.depends=s.depends.filter(dep=>dep!==id));state.selectedStep=state.steps[0]?.id;state.dagView.auto=true;render();return;}
  if(action==='dag-in')return zoomDAG(1.2);
  if(action==='dag-out')return zoomDAG(1/1.2);
  if(action==='dag-fit'){currentGraphView().auto=true;syncDAG();return;}
  if(action==='save-template'){state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}return openModal('Lưu thành template mới','Chỉ lưu trong bộ nhớ của prototype.',`<form id="template-form"><label class="label" for="template-name">Tên template</label><input id="template-name" name="name" required value="${esc(state.title)}"><div class="wizard-foot">${btn('Hủy','close-modal')}<button type="submit" class="btn primary">Lưu template</button></div></form>`);}
  if(action==='start'){
    state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}
    state.run={id:'run-'+Date.now().toString(36)+'-'+state.sessions.length,status:'running',plan:clone({title:state.title,star:state.star,output:state.output,steps:state.steps,templateId:state.templateId,cases:state.selectedCases,discussionDocs:state.discussionDocs,experts:experts.filter(e=>state.steps.some(s=>s.experts.includes(e.id)))}),results:[],trace:[],exit:null,shared:false};state.sessions.push(state.run);state.hasDraft=false;startSimulation(state.run);return go('running');
  }
  if(action==='dash-tab'){state.dashTab=button.dataset.tab;render();return;}
  if(action==='result-detail')return resultModal(id);
  if(action==='unexecuted')return toast('Bước chưa được thực hiện; không có kết luận.');
  if(action==='export')return openModal('Xuất kết quả','File chứa nhãn prototype, trạng thái cuối và các phần đã hoàn thành.',`<div class="grid2"><button class="card path-card" data-action="download" data-format="json"><span class="avatar">${ico('file')}</span><div><h3>JSON</h3><p>Plan, artifacts, tài liệu, exit và trace.</p></div></button><button class="card path-card" data-action="download" data-format="md"><span class="avatar blue">${ico('file')}</span><div><h3>Markdown</h3><p>Báo cáo để tiếp tục biên tập.</p></div></button></div>`);
  if(action==='download')return download(button.dataset.format);
  if(action==='share')return openModal('Chia sẻ toàn bộ case','Trong prototype, case chia sẻ xuất hiện tại Case Library của phiên trình duyệt này.',`<div class="notice amber">Chia sẻ bao gồm bối cảnh, tài liệu tham khảo, plan, ý kiến expert, kết quả và trace. Không có quyền xem một phần trong MVP đã chốt.</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.run.shared?'Đã chia sẻ ✓':'Chia sẻ case','confirm-share','primary',state.run.shared?'disabled':'')}</div>`);
  if(action==='confirm-share'){const r=state.run;r.shared=true;cases.push({id:'shared-'+r.id,title:r.plan.title,description:r.plan.star.task,owner:'Tran',date:'Vừa xong',rating:r.status==='completed'?'SAMPLE':'INCOMPLETE',summary:r.results.at(-1)?.summary||'Chưa có bước hoàn tất.',docs:[...new Set([...r.plan.discussionDocs,...r.plan.steps.flatMap(s=>s.docs)])],public:true,run:r});closeModal();render();return toast('Đã chia sẻ toàn bộ case trong phiên prototype.');}
  if(action==='session'){state.run=state.sessions[Number(button.dataset.index)];return go(state.run.status==='running'?'running':'dashboard');}
  if(action==='toggle-state'){state.showState=!state.showState;renderTools();return;}
  if(action==='reset')return location.reload();
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&!button.disabled){event.preventDefault();handleAction(button);}if(event.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',event=>{
  if($('#modal-root').firstChild){
    if(event.key==='Escape')closeModal();
    if(event.key==='Tab'){const focusable=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
    return;
  }
  if(event.target.id==='direct-message'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();sendDirectMessage();return;}
  if(event.target.closest('input,textarea,select,[contenteditable]'))return;
  if((event.key==='Enter'||event.key===' ')&&event.target.matches('tr[data-action],.expert-card-link')){event.preventDefault();handleAction(event.target);}
});
document.addEventListener('input',event=>{const e=event.target;if(e.hasAttribute('data-chat-draft')&&state.chatId)state.chatDrafts[state.chatId]=e.value;if(e.dataset.star)state.star[e.dataset.star]=e.value;if(e.dataset.expertField)state.expertDraft[e.dataset.expertField]=e.value;if(e.dataset.field){state[e.dataset.field]=e.value;if(['expertQuery','caseQuery','directExpertQuery'].includes(e.dataset.field))render();}if(e.dataset.stepField){const s=stepById(state.selectedStep);s[e.dataset.stepField]=e.type==='number'?Number(e.value):e.value;}if(state.showState)renderTools();});
document.addEventListener('change',async event=>{
  const e=event.target;
  if(e.hasAttribute('data-direct-expert')){state.directExpertId=e.value;render();}
  if(e.dataset.stepList){const s=stepById(state.selectedStep),key=e.dataset.stepList;s[key]=e.checked?[...s[key],e.value]:s[key].filter(x=>x!==e.value);if(key==='experts'&&s.experts.length>1&&s.rounds===0)s.rounds=1;state.validation=validatePlan();render();}
  if(e.dataset.stepField)render();
  if(e.dataset.field&&isPlanEditor())render();
  if(e.hasAttribute('data-expert-skill')){state.expertDraft.skills=e.checked?[...state.expertDraft.skills,e.value]:state.expertDraft.skills.filter(s=>s!==e.value);}
  if(e.hasAttribute('data-template-case')){state.selectedCases=e.checked?[...state.selectedCases,e.value]:state.selectedCases.filter(id=>id!==e.value);render();}
  if(e.hasAttribute('data-discussion-doc')){state.discussionDocs=e.checked?[...state.discussionDocs,e.value]:state.discussionDocs.filter(id=>id!==e.value);render();}
  if(e.dataset.actionChange==='domain'){state.expertDomain=e.value;render();}
  if(e.id==='preview-state'){
    if(!state.run){toast('Review và Start một discussion để xem các trạng thái mẫu.');e.value='';return;}
    if(e.value==='running'){startSimulation(state.run);go('running');}else if(e.value)finishFixture(e.value);
  }
  if(e.id==='document-upload'){
    for(const file of e.files){const isText=/\.(txt|md|csv)$/i.test(file.name),id='U'+(documents.filter(d=>d.id.startsWith('U')).length+1);documents.push({id,name:file.name,kind:'Tài liệu tải lên',metadataOnly:!isText,text:isText?await file.text():'Chưa trích xuất nội dung trong frontend prototype. File: '+file.name});state.discussionDocs.push(id);}
    render();toast('Đã thêm tài liệu vào hồ sơ của phiên này.');
  }
});
let graphDrag=null;
document.addEventListener('pointerdown',event=>{const viewport=event.target.closest('#dag-viewport');if(!viewport||event.target.closest('button')||event.button!==0)return;const view=currentGraphView();graphDrag={pointer:event.pointerId,x:event.clientX,y:event.clientY,originX:view.x,originY:view.y};viewport.setPointerCapture(event.pointerId);viewport.classList.add('dragging');});
document.addEventListener('pointermove',event=>{if(!graphDrag||event.pointerId!==graphDrag.pointer)return;const view=currentGraphView();view.auto=false;view.x=graphDrag.originX+event.clientX-graphDrag.x;view.y=graphDrag.originY+event.clientY-graphDrag.y;syncDAG();});
function endGraphDrag(){graphDrag=null;$('#dag-viewport')?.classList.remove('dragging');}
document.addEventListener('pointerup',endGraphDrag);
document.addEventListener('pointercancel',endGraphDrag);
document.addEventListener('wheel',event=>{if(!event.target.closest('#dag-viewport'))return;event.preventDefault();zoomDAG(event.deltaY>0?1/1.08:1.08);},{passive:false});
document.addEventListener('submit',event=>{
  if(event.target.id==='direct-chat-form'){event.preventDefault();sendDirectMessage();return;}
  if(event.target.id==='expert-form'){
    event.preventDefault();const form=new FormData(event.target),id=event.target.dataset.id,role=form.get('role').trim(),domain=form.get('domain').trim()||'General';
    const data={role,domain,approach:form.get('approach').trim(),prompt:form.get('prompt').trim(),skills:form.getAll('skills'),initials:role.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),color:'purple'};
    const expertId=id||'expert-'+Date.now().toString(36);if(id)Object.assign(expertById(id),data);else experts.push({id:expertId,...data});openExpert(expertId);toast(id?'Đã cập nhật expert.':'Expert đã sẵn sàng để gán vào plan.');
  }
  if(event.target.id==='template-form'){
    event.preventDefault();const name=new FormData(event.target).get('name').trim(),id='template-'+Date.now();templates.push({id,title:name,description:'Template lưu từ bản plan đang chỉnh. Chỉ tồn tại trong phiên prototype.',tag:'Custom',icon:'graph',steps:state.steps.length,output:state.output,definition:clone(state.steps)});closeModal();render();toast('Đã lưu template mới trong bộ nhớ.');
  }
});
// Preserve the selected custom template definition when starting a new discussion.
const originalApplyTemplate=applyTemplate;
applyTemplate=function(id){const t=templates.find(t=>t.id===id);if(t?.definition){state.templateId=id;state.steps=clone(t.definition);state.selectedStep=state.steps[0].id;state.output=t.output;}else originalApplyTemplate(id);};
// Old variant links resolve to the selected design, without retaining a switcher.
const cleanUrl=new URL(location.href);if(cleanUrl.searchParams.has('variant')){cleanUrl.searchParams.delete('variant');history.replaceState({},'',cleanUrl);}
render();
